# Code snippet to test regex pattern matching
import re

def test_regex(pattern, test_string):
    try:
        assert re.search(pattern, test_string) is not None, "Pattern did not match the test string."
        print("Pattern matched successfully.")
    except re.error:
        print("Invalid regex pattern.")

# Example usage
test_regex(r'hello\s(you|world)', 'hello world')
